const paddle = new Paddle(process.env.PADDLE_API_KEY);

// Creates a Paddle transaction for the household's subscription and returns
// its hosted checkout URL. Paddle creates the subscription once it is paid.
app.post('/checkout', async (req, res) => {
  const { householdId } = req.body ?? {};
  if (!householdId) return res.status(400).json({ error: 'householdId is required' });
  try {
    const txn = await paddle.transactions.create({
      items: [{ priceId: process.env.PADDLE_PRICE_ID, quantity: 1 }],
      customData: { household_id: String(householdId) },
    });
    res.status(201).json({ transactionId: txn.id, checkoutUrl: txn.checkout?.url });
  } catch (err) {
    console.error('paddle checkout failed', err);
    res.status(502).json({ error: 'payment provider error' });
  }
});

